// Given: the demo harness behind `npm run demo:N`. Do not edit this file.
// Picks the demo from ?demo=N and shows a friendly message when it needs an
// exercise you have not finished yet (its stubs throw "TODO: ...").
import { demo0 } from "./demo0";
import type { Demo } from "./types";

const demos: Record<string, Demo> = { "0": demo0 };

const app = document.getElementById("app")!;
const id = new URLSearchParams(location.search).get("demo") ?? "0";
const demo = demos[id];

const nav = document.createElement("nav");
nav.innerHTML = ["0", "1", "2", "3", "4", "5", "6"]
  .map((n) => `<a href="?demo=${n}"${n === id ? ' aria-current="page"' : ""}>${n}</a>`)
  .join("");
app.appendChild(nav);

const h1 = document.createElement("h1");
const p = document.createElement("p");
const stage = document.createElement("div");
app.append(h1, p, stage);

if (!demo) {
  h1.textContent = `Demo ${id}`;
  p.textContent = `Demo ${id} arrives with Module ${id}.`;
} else {
  h1.textContent = demo.title;
  p.textContent = demo.description;
  document.title = demo.title;
  try {
    demo.mount(stage);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    const box = document.createElement("pre");
    box.className = "todo";
    box.textContent = msg.startsWith("TODO")
      ? `This demo needs code you have not written yet:\n\n  ${msg}\n\nRun the tests for that exercise, then reload.`
      : `The demo stopped with an error:\n\n  ${msg}`;
    stage.replaceChildren(box);
    console.error(e);
  }
}
